import re
from functools import cmp_to_key

def parse_version(v):
    if v.startswith('v'):
        v = v[1:]
    pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:(?:0|[1-9]\d*|[0-9]*[a-zA-Z-][0-9a-zA-Z-]*)\.)*(?:0|[1-9]\d*|[0-9]*[a-zA-Z-][0-9a-zA-Z-]*))?)?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$
    match = re.match(pattern, v)
    if not match:
        raise ValueError(f'Invalid: {v!r}')
    major, minor, patch = int(match.group(1)), int(match.group(2)), int(match.group(3))
    pre = []
    if match.group(4):
        for ident in match.group(4).split('.'):
            if ident.isdigit():
                if len(ident) > 1 and ident[0] == '0':
                    raise ValueError(f'Invalid: {v!r}')
                pre.append(int(ident))
            else:
                if not re.match(r'^[0-9a-zA-Z-]+$', ident):
                    raise ValueError(f'Invalid: {v!r}')
                pre.append(ident)
    build = match.group(5)
    return (major, minor, patch, pre, build)

def compare_parsed(pa, pb):
    for a, b in zip(pa[:3], pb[:3]):
        if a < b: return -1
        if a > b: return 1
    ha, hb = pa[3] is not None, pb[3] is not None
    if ha and hb:
        for a, b in zip(pa[3], pb[3]):
            ai, bi = isinstance(a, int), isinstance(b, int)
            if ai and bi:
                if a < b: return -1
                if a > b: return 1
            elif ai: return -1
            elif bi: return 1
            else:
                if a < b: return -1
                if a > b: return 1
        if len(pa[3]) < len(pb[3]): return -1
        if len(pa[3]) > len(pb[3]): return 1
        return 0
    if ha: return -1
    if hb: return 1
    pa_b, pb_b = pa[4], pb[4]
    if pa_b is not None and pb_b is not None:
        if pa_b < pb_b: return -1
        if pa_b > pb_b: return 1
        return 0
    if pa_b is not None: return 1
    if pb_b is not None: return -1
    return 0

def compare(a, b):
    pa, pb = parse_version(a), parse_version(b)
    return compare_parsed(pa, pb)

def sort_versions(versions):
    return sorted(versions, key=cmp_to_key(compare))


if __name__ == '__main__':
    print(compare('1.0.0', '2.0.0'))
    print(sort_versions(['1.0.0', '2.0.0', '1.0.1']))
